vec2 ab = b - a;
vec2 ac = c - a;
vec2 pa = a - p;

double dot_ac_ac = ac.x * ac.x + ac.y * ac.y;
double dot_ac_ab = ac.x * ab.x + ac.y * ab.y;
double dot_ab_ab = ab.x * ab.x + ab.y * ab.y;
double dot_ac_pa = ac.x * pa.x + ac.y * pa.y;
double dot_ab_pa = ab.x * pa.x + ab.y * pa.y;

double denominator = dot_ac_ac * dot_ab_ab - dot_ac_ab * dot_ac_ab;
if (std::abs(denominator) < 1e-10) {
    return vec3{-1, 1, 1}; // Degenerate triangle, return invalid barycentric coordinates
}

double v = (dot_ab_ab * dot_ac_pa - dot_ac_ab * dot_ab_pa) / denominator;
double w = (dot_ac_ac * dot_ab_pa - dot_ac_ab * dot_ac_pa) / denominator;
double u = 1.0 - v - w;

return vec3{u, v, w};

